    title: { ar: 'مؤرخ الإسلام وشيخ المحدثين', az: 'İslam tarixçisi, mühəddislərin şeyxi', en: 'Historian of Islam, shaykh of the hadith scholars', ru: 'Историк ислама, шейх мухаддисов', tr: 'İslâm tarihçisi, muhaddislerin şeyhi' },
    born: { h: 673, g: 1274 },
